=<!DOCTYPE html>
<html>
<head>
  <style>
    body {
      /* Fondo oscuro (casi negro) para la página */
      background-color: #121212;
      font-family: sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      margin: 0;
      color: #e0e0e0; /* Texto base gris claro */
    }
    .card {
      /* Fondo de la tarjeta un poco más claro que el body para dar profundidad */
      background-color: #1e1e1e;
      padding: 40px;
      border-radius: 15px;
      text-align: center;
      /* Sombra más intensa para que se note en lo oscuro */
      box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);
      border: 1px solid #333; /* Borde sutil */
    }
    h1 {
      /* Verde brillante/pastel para que resalte sobre negro */
      color: #66bb6a;
      margin-bottom: 20px;
    }
    p {
      color: #b0bec5; /* Gris azulado para el texto secundario */
    }
    b {
      color: #ffffff; /* El nombre del archivo en blanco puro */
    }
    a {
      /* Verde claro para el enlace */
      color: #81c784;
      text-decoration: none;
      font-weight: bold;
      border: 1px solid #81c784;
      padding: 10px 20px;
      border-radius: 5px;
      transition: all 0.3s ease;
      display: inline-block;
      margin-top: 15px;
    }
    /* Efecto Hover para el botón */
    a:hover {
      background-color: #81c784;
      color: #121212;
    }
  </style>
</head>
<body>
  <div class='card'>
    <h1>🚀 ¡Archivo Subido!</h1>
    <p>Tu documento <b>{{ $json.name }}</b> ya está seguro en Google Drive.</p>
    <a href='{{ $json.webViewLink }}' target='_blank'>Ver archivo en Drive</a>
  </div>
</body>
</html>
